def calculate_total_cost():
    # Cost of one glass
    cost_one_glass = 5

    # Discounted price for every second glass (60% of original price)
    discounted_price = cost_one_glass * 0.6

    # Total number of glasses Kylar wants to buy
    total_glasses = 16

    # Calculate the total cost, considering that every second glass is discounted
    total_cost = 0
    for i in range(total_glasses):
        if (i + 1) % 2 == 0:  # If the glass is at an even position (second, fourth, sixth, etc.)
            total_cost += discounted_price
        else:
            total_cost += cost_one_glass

    return round(total_cost, 3)

print(f"${calculate_total_cost():.3g}")
